package org.beckenburg;

import javax.swing.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.imageio.ImageIO;
import org.beckenburg.editor.*;

/** Real human GLB editing, source-backed native persistence and actual game publication. */
public final class AssetImportGlbGuiTest {
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private static Object field(Object o,String name)throws Exception{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private static Object call(Object o,String name,Class<?>[] types,Object... args)throws Exception{var m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}
    private static void button(AssetImportDialog ui,String name)throws Exception{((JButton)field(ui,name)).doClick();}
    private static boolean ready(AssetImportDialog ui){try{return !((Boolean)field(ui,"busy"))&&((JButton)field(ui,"apply")).isEnabled();}catch(Exception e){throw new RuntimeException(e);}}
    private static boolean reviewed(AssetImportDialog ui){try{return !((Boolean)field(ui,"busy"))&&field(ui,"modelingPreview")!=null;}catch(Exception e){throw new RuntimeException(e);}}
    private static void await(java.util.function.BooleanSupplier condition)throws Exception{long end=System.nanoTime()+30_000_000_000L;while(System.nanoTime()<end){var done=new java.util.concurrent.atomic.AtomicBoolean();SwingUtilities.invokeAndWait(()->done.set(condition.getAsBoolean()));if(done.get())return;Thread.sleep(20);}throw new AssertionError("Human GLB operation did not complete");}
    private static void selectFace(AssetImportDialog ui,EditorTopologyProject project)throws Exception{
        ((JComboBox<?>)field(ui,"meshView")).setSelectedItem(EditorMeshPicking.Projection.SIDE);((JComboBox<?>)field(ui,"selectionMode")).setSelectedItem("FACE");var face=project.mesh().triangles().get(0);var p=EditorMeshPicking.Projection.SIDE.project((face.a().x()+face.b().x()+face.c().x())/3,(face.a().y()+face.b().y()+face.c().y())/3,(face.a().z()+face.b().z()+face.c().z())/3);
        var reference=call(ui,"workingReference",new Class<?>[0]);var viewport=call(ui,"viewport",new Class<?>[]{List.class,int.class,int.class},reference,0,ui.workingViewportWidth());int x=(Integer)call(viewport,"x",new Class<?>[]{double.class},p.x()),y=(Integer)call(viewport,"y",new Class<?>[]{double.class},p.y());var canvas=(JPanel)field(ui,"preview");canvas.dispatchEvent(new MouseEvent(canvas,MouseEvent.MOUSE_PRESSED,System.currentTimeMillis(),0,x,y,1,false,MouseEvent.BUTTON1));check(((EditorMeshPicking.Hit)field(ui,"selectedHit")).faceId()==0,"Real native GLB triangle selected in side projection");
    }
    private static void capture(AssetImportDialog ui,String name,Path file)throws Exception{var content=((JDialog)field(ui,name)).getContentPane();var image=new BufferedImage(content.getWidth(),content.getHeight(),BufferedImage.TYPE_INT_ARGB);var g=image.createGraphics();try{content.printAll(g);}finally{g.dispose();}ImageIO.write(image,"png",file.toFile());}
    private static void near(double a,double b){check(Math.abs(a-b)<1e-5*Math.max(1,Math.abs(b)),"Actual runtime coordinate differs");}
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("human-source-glb-");String oldHome=System.getProperty("user.home");System.setProperty("user.home",root.toString());Path output=Path.of("build/editor-agent-evidence").toAbsolutePath();Files.createDirectories(output);Path source=root.resolve("assembly.glb");byte[] original=EditorGlbAuthoringTest.externalFixture();Files.write(source,original);
        var ui=new AtomicReference<AssetImportDialog>();var project=new AtomicReference<EditorTopologyProject>();var published=new AtomicReference<String>();var initial=new AtomicReference<EditorTopologyProject.State>();
        try{
            SwingUtilities.invokeAndWait(()->{var dock=new AssetImportDialog(null,published::set);ui.set(dock);try{((JDialog)field(dock,"dialog")).setVisible(true);}catch(Exception e){throw new RuntimeException(e);}dock.loadSource(source);});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();project.set((EditorTopologyProject)field(dock,"topologyProject"));initial.set(project.get().snapshot());check(initial.get().glbSource()!=null&&initial.get().vertices().size()==8&&Arrays.equals(EditorGlbWriter.encode(project.get().mesh()),original),"Human GLB import owns actual source-backed indexed native state, not flattened editable proxy");var row=(DefaultListModel<?>)field(dock,"partRows");check(row.size()==2&&row.get(0).toString().contains("Panel A")&&row.get(1).toString().contains("Panel B"),"Native parts list displays actual original node names");check(dock.exportGlb(output.resolve("glb-human-exact.glb"))&&Arrays.equals(Files.readAllBytes(output.resolve("glb-human-exact.glb")),original),"Human no-edit GLB copy is exact original bytes");
                long id=initial.get().vertices().stream().filter(v->v.part().equals("glb_node_1")).findFirst().orElseThrow().id();((JSpinner)field(dock,"vertexId")).setValue(id);var vertex=project.get().snapshot().vertices().stream().filter(v->v.id()==id).findFirst().orElseThrow();((JSpinner)field(dock,"vertexX")).setValue(vertex.x()+.25);((JSpinner)field(dock,"vertexZ")).setValue(vertex.z()+.1);button(dock,"moveVertex");check(!project.get().snapshot().equals(initial.get()),"Real coordinate controls modify source-backed native instance");button(dock,"undoMesh");check(project.get().snapshot().equals(initial.get()),"Human undo restores original source-backed state");button(dock,"redoMesh");selectFace(dock,project.get());dock.openMaterials();((JSpinner)field(dock,"materialRotation")).setValue(40d);((JTabbedPane)field(dock,"materialTools")).setSelectedIndex(1);((JSpinner)field(dock,"uvFirst")).setValue(.5);button(dock,"previewUv");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var before=project.get().snapshot();capture(dock,"materialDialog",output.resolve("glb-human-uv-preview.png"));button(dock,"cancelFaceEdit");check(project.get().snapshot()==before,"Source-backed UV cancel preserves native authority");button(dock,"previewUv");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var edit=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");button(dock,"applyFaceEdit");check(project.get().snapshot()==edit.snapshot(),"Human Apply installs exact GLB native candidate");button(dock,"saveMesh");check(EditorTopologyProject.open(project.get().documentPath()).snapshot().equals(project.get().snapshot()),"Human native v4 fresh reopen preserves original nodes, PNG, edits and metadata");check(dock.exportGlb(output.resolve("glb-human-edited.glb")),"Human source-preserving GLB export");EditorGlbWriter.validate(project.get().mesh(),Files.readAllBytes(output.resolve("glb-human-edited.glb")));}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));SwingUtilities.invokeAndWait(()->{try{button(ui.get(),"apply");}catch(Exception e){throw new RuntimeException(e);}});await(()->published.get()!=null);
            byte[] actual=ImportedAssetLibrary.read(published.get());check(!Arrays.equals(actual,original),"Published GLB contains actual edits rather than unchanged original bytes");EditorGlbWriter.validate(project.get().mesh(),actual);var runtime=GlbProps.model(published.get());var expected=project.get().mesh().triangles();check(runtime.triangles().size()==4,"Actual game retains both source instances");
            for(int i=0;i<runtime.triangles().size();i++){var a=List.of(runtime.triangles().get(i).a(),runtime.triangles().get(i).b(),runtime.triangles().get(i).c());var b=List.of(expected.get(i).a(),expected.get(i).b(),expected.get(i).c());for(int j=0;j<3;j++){near(a.get(j).x(),b.get(j).x());near(a.get(j).y(),b.get(j).y());near(a.get(j).z(),b.get(j).z());near(a.get(j).u(),b.get(j).u());near(a.get(j).v(),b.get(j).v());}}
            check(GlbProps.sampleRgba(runtime.triangles().get(0).material(),.75,.25)==0x8000ff00,"Actual imported external GLB follows source upper-left texture origin");check(EditorTopologyProject.open(ImportedAssetLibrary.root().resolve(published.get()+".authoring.btop")).snapshot().equals(project.get().snapshot()),"Publication archives exact native source-backed authoring state");check(Arrays.equals(Files.readAllBytes(source),original),"Original source GLB cannot be rewritten by human edits/export/publication");
            await(()->{try{return !((Boolean)field(ui.get(),"materialRendering"))&&((JLabel)field(ui.get(),"materialRuntime")).getIcon()!=null;}catch(Exception e){throw new RuntimeException(e);}});SwingUtilities.invokeAndWait(()->{try{capture(ui.get(),"dialog",output.resolve("glb-human-model-window.png"));capture(ui.get(),"materialDialog",output.resolve("glb-human-material-window.png"));}catch(Exception e){throw new RuntimeException(e);}});
            Files.write(output.resolve("glb-human-original.glb"),original);Files.write(output.resolve("glb-human-runtime.glb"),actual);Files.copy(project.get().documentPath(),output.resolve("glb-human-model.btop"),StandardCopyOption.REPLACE_EXISTING);System.out.println("PASS human source-backed GLB: actual matrix/ancestor mesh, independent instance vertex/UV controls, shared history/native v4, exact no-edit/source metadata and original PNG, real GLB export/publication/archive/game UVs and screenshots");
        }finally{SwingUtilities.invokeAndWait(()->{if(ui.get()!=null)try{((JDialog)field(ui.get(),"dialog")).dispose();}catch(Exception e){throw new RuntimeException(e);}});System.setProperty("user.home",oldHome);try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    }
}
